    three_prime_factors = [0] * (MAX + 1)  # Array to mark numbers with exactly 3 prime factors

    # Sieve of Eratosthenes variant for counting semiprimes and numbers with 3 prime factors
    for i in range(2, MAX + 1):
        if semiprime[i] == 0:  # i is a prime number
            for j in range(i, MAX // i + 1):
                if semiprime[j * i] == 0:
                    semiprime[j * i] = 1  # Mark as semiprime
                else:
                    three_prime_factors[j * i] += 1  # Increment count of prime factors

